static char *inject_ml_src(const char *src) {
  const char *hp;
  char *host;
  char *mix;
  size_t hl;
  size_t ol;
  if (!src) return xstrdup("");
  if (strstr(src, "fn nt_from(")) return xstrdup(src);
  hp = find_ml_host();
  if (!hp) return xstrdup(src);
  host = load_with_imports(hp, 1);
  hl = strlen(host);
  ol = strlen(src);
  mix = (char *)malloc(hl + ol + 2);
  if (!mix) die("oom");
  memcpy(mix, host, hl);
  mix[hl] = '\n';
  memcpy(mix + hl + 1, src, ol + 1);
  free(host);
  return mix;
}
static char *load_with_imports(const char *path, int depth) {
  if (depth > 32) die("import nest too deep");
  char *src = read_file(path);
  char *dir = dirname_dup(path);
  size_t n = strlen(src);
  size_t i = 0;
  char *acc = xstrdup("");
  size_t acc_len = 0;
  while (1) {
    i = skip(src, i, n);
    if (!starts_kw(src, i, n, "import")) break;
    i = skip(src, i + 6, n);
    if (i >= n || src[i] != '"') die("expected string after import");
    size_t ii = i;
    char *spec = parse_string(src, &ii, n);
    i = skip(src, ii, n);
    if (i < n && src[i] == ';') i++;
    char *dep_path = join_path(dir, spec);
    free(spec);
    char *dep = load_with_imports(dep_path, depth + 1);
    free(dep_path);
    size_t dep_len = strlen(dep);
    char *nacc = (char *)malloc(acc_len + dep_len + 2);
    if (!nacc) die("oom");
    memcpy(nacc, acc, acc_len);
    memcpy(nacc + acc_len, dep, dep_len);
    nacc[acc_len + dep_len] = '\n';
    nacc[acc_len + dep_len + 1] = 0;
    free(acc);
    free(dep);
    acc = nacc;
    acc_len += dep_len + 1;
  }
  size_t rest = n - i;
  char *out = (char *)malloc(acc_len + rest + 1);
  if (!out) die("oom");
  memcpy(out, acc, acc_len);
  memcpy(out + acc_len, src + i, rest);
  out[acc_len + rest] = 0;
  free(acc);
  free(src);
  free(dir);
  if (depth == 0 && strstr(path, "native_ml.kenga") == NULL &&
      strstr(path, "ml_host.kenga") == NULL && strstr(out, "fn nt_from(") == NULL) {
    char *mix = inject_ml_src(out);
    free(out);
    out = mix;
  }
  return out;
}
